# ---- primary/secondary type 규칙 (semantic type + data_type + 수동 override)
BASE = {"SYMPTOM": "SYMPTOM", "SIGN": "SIGN", "DISEASE_HISTORY": "MEDICAL_HISTORY", "FAMILY_HISTORY": "FAMILY_HISTORY", "MEDICATION": "MEDICATION", "PROCEDURE_HISTORY": "PROCEDURE", "EXPOSURE": "EXPOSURE", "LIFESTYLE": "LIFESTYLE", "DEMOGRAPHIC": "DEMOGRAPHIC", "SOCIAL": "LIFESTYLE", "TRAVEL": "TRAVEL", "PAIN_ATTRIBUTE": "SYMPTOM", "LESION_ATTRIBUTE": "SIGN", "SYMPTOM_MODIFIER": "TEMPORAL"}
OVR = {"E_54": ("SYMPTOM", "OTHER(pain character)"), "E_55": ("ANATOMICAL_LOCATION", "SYMPTOM"), "E_57": ("ANATOMICAL_LOCATION", "SYMPTOM"), "E_133": ("ANATOMICAL_LOCATION", "SIGN"), "E_152": ("ANATOMICAL_LOCATION", "SYMPTOM"), "E_56": ("SEVERITY", "SYMPTOM"), "E_58": ("SEVERITY", "SYMPTOM"), "E_134": ("SEVERITY", "SIGN"), "E_136": ("SEVERITY", "SYMPTOM"), "E_132": ("SEVERITY", "SIGN"), "E_59": ("TEMPORAL", "SYMPTOM"), "E_13": ("TEMPORAL", "SEVERITY"), "E_215": ("TEMPORAL", "SYMPTOM"), "E_216": ("SYMPTOM", "TEMPORAL"), "E_217": ("SYMPTOM", "TEMPORAL"), "E_218": ("TEMPORAL", "SYMPTOM"), "E_219": ("TEMPORAL", "SYMPTOM"), "E_220": ("SYMPTOM", "ANATOMICAL_LOCATION"), "E_221": ("SYMPTOM", "TEMPORAL"), "E_33": ("SYMPTOM", "TEMPORAL"), "E_90": ("SYMPTOM", "TEMPORAL"),
       "E_46": ("MEDICAL_HISTORY", "FREQUENCY"), "E_72": ("MEDICAL_HISTORY", "FREQUENCY"), "E_101": ("MEDICAL_HISTORY", "PROCEDURE"), "E_167": ("PREGNANCY_REPRODUCTIVE", ""), "E_141": ("PREGNANCY_REPRODUCTIVE", "TEMPORAL"), "E_11": ("PREGNANCY_REPRODUCTIVE", "TEMPORAL"), "E_145": ("SYMPTOM", "PREGNANCY_REPRODUCTIVE"), "E_163": ("SYMPTOM", "PREGNANCY_REPRODUCTIVE"), "E_160": ("MEDICAL_HISTORY", "COMPOSITE"), "E_8": ("PROCEDURE", "MEDICAL_HISTORY"), "E_137": ("PROCEDURE", ""), "E_196": ("PROCEDURE", "TEMPORAL"), "E_1": ("MEDICATION", "MEDICAL_HISTORY"), "E_124": ("MEDICAL_HISTORY", "MEDICATION"), "E_71": ("MEDICAL_HISTORY", "MEDICATION"), "E_104": ("MEDICAL_HISTORY", "MEDICATION"), "E_153": ("MEDICAL_HISTORY", "MEDICATION"), "E_147": ("MEDICATION", "PROCEDURE"), "E_209": ("MEDICAL_HISTORY", "PROCEDURE"),
       "E_17": ("DEMOGRAPHIC", ""), "E_208": ("DEMOGRAPHIC", "TEST_RESULT"), "E_70": ("RISK_FACTOR", "DEMOGRAPHIC"), "E_226": ("RISK_FACTOR", ""), "E_227": ("RISK_FACTOR", "MEDICAL_HISTORY"), "E_7": ("LIFESTYLE", "RISK_FACTOR"), "E_48": ("LIFESTYLE", "RISK_FACTOR"), "E_49": ("EXPOSURE", "LIFESTYLE"), "E_110": ("RISK_FACTOR", "TEMPORAL"), "E_115": ("RISK_FACTOR", "LIFESTYLE"), "E_189": ("EXPOSURE", "RISK_FACTOR"), "E_61": ("LIFESTYLE", "RISK_FACTOR"), "E_204": ("TRAVEL", "TEMPORAL"), "E_42": ("EXPOSURE", "SYMPTOM"), "E_187": ("EXPOSURE", "TEMPORAL"), "E_150": ("SYMPTOM", "TEMPORAL"), "E_129": ("SIGN", "COMPOSITE"), "E_130": ("SIGN", "OTHER(color)"), "E_131": ("SIGN", ""), "E_135": ("SIGN", "SEVERITY"), "E_53": ("SYMPTOM", "")}
def types(e):
    s = sem.loc[e]; p = BASE.get(s.evidence_type, "OTHER"); sec = []
    if e in OVR: p, s2 = OVR[e]; sec = [s2] if s2 else []
    if s.operator in ("AND", "OR") and s.concept_2 and "COMPOSITE" not in sec: sec.append("COMPOSITE")
    if s.temporality not in ("current", "static", "ever", "") and "TEMPORAL" not in sec and p != "TEMPORAL": sec.append("TEMPORAL")
    if s.evidence_type == "FAMILY_HISTORY" and p != "FAMILY_HISTORY": sec.append("FAMILY_HISTORY")
    return p, ";".join(dict.fromkeys(sec))
def vtype(v): return {"B": "binary", "C": "categorical/ordinal", "M": "multi-choice"}[v["data_type"]]
rows, vl, elig_rows, rq = [], [], [], []
for e, v in sorted(ev.items(), key=lambda x: int(x[0][2:])):
    s, c, l = sem.loc[e], em.loc[e], el.loc[e]; p, sec = types(e); prev = "ELIGIBLE_83" if l.finding_eligible == "True" else "EXCLUDED"
    pv = v["possible-values"]; nval = len(pv) if isinstance(pv, list) else 0; vm = v.get("value_meaning", {}); ex_vals = "; ".join(list(m["en"] for m in vm.values())[:4]) if vm else (f"{pv[0]}..{pv[-1]}" if nval else "yes/no")
    # ---- value-level 구조
